describe('List Item Reordering by Drag and Drop', () => {
  beforeEach(() => {
    cy.visit('/list-items');
  });

  it('should successfully reorder list items by dragging and dropping', () => {
    // Verify initial list order
    cy.get('[data-testid="list-item-1"]').should('contain', 'First Item');
    cy.get('[data-testid="list-item-2"]').should('contain', 'Second Item');
    cy.get('[data-testid="list-item-3"]').should('contain', 'Third Item');

    // Drag the first item to the end
    cy.get('[data-testid="list-item-1"]').trigger('mousedown', { button: 0 });
    cy.get('[data-testid="list-item-1"]').trigger('mousemove', { clientX: 500, clientY: 500 });
    cy.get('[data-testid="list-item-1"]').trigger('mouseup', { force: true });

    // Verify the new order
    cy.get('[data-testid="list-item-1"]').should('contain', 'First Item');
    cy.get('[data-testid="list-item-2"]').should('contain', 'Second Item');
    cy.get('[data-testid="list-item-3"]').should('contain', 'Third Item');
    cy.get('[data-testid="list-item-1"]').should('have.attr', 'data-order', '3');
    cy.get('[data-testid="list-item-2"]').should('have.attr', 'data-order', '1');
    cy.get('[data-testid="list-item-3"]').should('have.attr', 'data-order', '2');

    // Verify API call for reordering
    cy.intercept('POST', '/api/list-items/reorder').as('reorderItems');
    cy.get('[data-testid="list-item-1"]').trigger('mousedown', { button: 0 });
    cy.get('[data-testid="list-item-1"]').trigger('mousemove', { clientX: 500, clientY: 500 });
    cy.get('[data-testid="list-item-1"]').trigger('mouseup', { force: true });
    cy.wait('@reorderItems');

    // Verify success message
    cy.get('[data-testid="success-message"]').should('be.visible').should('contain', 'List reordered successfully');
  });

  it('should handle drag and drop with empty list or invalid items', () => {
    // Navigate to an empty list
    cy.visit('/list-items/empty');

    // Verify empty state message
    cy.get('[data-testid="empty-state-message"]').should('be.visible').should('contain', 'No items in this list');

    // Attempt to drag an item (should not exist)
    cy.get('[data-testid="list-item-1"]').should('not.exist');

    // Verify no reorder API call is made
    cy.intercept('POST', '/api/list-items/reorder').as('reorderItems');
    cy.get('[data-testid="list-item-1"]').trigger('mousedown', { button: 0 });
    cy.get('[data-testid="list-item-1"]').trigger('mousemove', { clientX: 500, clientY: 500 });
    cy.get('[data-testid="list-item-1"]').trigger('mouseup', { force: true });

    cy.wait(100); // Wait for potential async operations
    cy.get('[data-testid="empty-state-message"]').should('be.visible');

    // Verify no error message appears
    cy.get('[data-testid="error-message"]').should('not.exist');
  });
});
